<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Workforce Experience · Atlas</title><link rel="stylesheet" href="<?=esc(url_for('assets/app.css'))?>"></head><body class="standalone-with-nav"><?=standaloneSidebar($navGroups,'workforce-experience',$admin,$org,$user,$location)?><main class="page-wrap standalone-workspace"><header class="page-header"><div><p class="eyebrow">PHASES 11–15</p><h1>Workforce experience</h1><p>Delivery templates, compliance forecasting, labor safeguards, and transparent scheduling guidance.</p></div><a class="button secondary" href="<?=esc(url_for('mobile-tools'))?>">Mobile experience</a></header><?php if($notice):?><div class="page-flash success"><span>✓</span><?=esc($notice['message'])?></div><?php endif;?>
<section class="planning-grid"><article class="panel"><h2>Notification templates</h2><form method="post" class="stack-form"><?=Csrf::field()?><input type="hidden" name="action" value="save_notification_template"><label>Event key<input name="event_key" required placeholder="schedule_published"></label><label>Channel<select name="channel"><option value="in_app">In app</option><option value="email">Email</option><option value="push">Push</option></select></label><label>Subject<input name="subject_template" required></label><label>Body<textarea name="body_template" rows="4" required></textarea></label><button class="button primary">Save template</button></form><?php foreach($notificationOperations['templates'] as $template):?><div class="planning-row"><span><strong><?=esc($template['event_key'])?></strong><small><?=esc($template['channel'].' · '.$template['subject_template'])?></small></span></div><?php endforeach;?></article>
<article class="panel"><h2>Delivery health</h2><?php $failed=0;$queued=0;foreach($notificationOperations['deliveries'] as $delivery){if($delivery['status']==='failed')$failed++;if($delivery['status']==='queued')$queued++;}?><div class="summary-grid"><div class="metric-card blue"><strong><?=$queued?></strong><span>Queued</span></div><div class="metric-card coral"><strong><?=$failed?></strong><span>Failed</span></div></div><?php foreach(array_slice($notificationOperations['deliveries'],0,20) as $delivery):?><div class="planning-row"><span><strong><?=esc($delivery['staff_name'].' · '.$delivery['channel'])?></strong><small><?=esc($delivery['status'].($delivery['failure_message']?' · '.$delivery['failure_message']:''))?></small></span></div><?php endforeach;?><?php if(!$notificationOperations['deliveries']):?><div class="inline-empty"><strong>No outbound deliveries queued</strong><p>The delivery ledger is ready for an email or push worker.</p></div><?php endif;?></article>
<article class="panel"><h2>Credential requirements</h2><form method="post" class="stack-form"><?=Csrf::field()?><input type="hidden" name="action" value="require_position_credential"><label>Position<select name="position_id"><?php foreach($data['positions'] as $position):?><option value="<?=$position['id']?>"><?=esc($position['name'])?></option><?php endforeach;?></select></label><label>Credential<select name="credential_type_id"><?php foreach($credentialTypes as $type):?><option value="<?=$type['id']?>"><?=esc($type['name'])?></option><?php endforeach;?></select></label><button class="button primary">Require credential</button></form><?php foreach($credentialCompliance['requirements'] as $requirement):?><div class="planning-row"><span><strong><?=esc($requirement['position_name'])?></strong><small><?=esc($requirement['credential_name'])?></small></span></div><?php endforeach;?></article>
<article class="panel"><h2>Compliance forecast</h2><?php foreach($credentialCompliance['forecast'] as $row):$gap=(int)$row['required_count']-(int)$row['compliant_count'];?><div class="planning-row"><span><strong><?=esc($row['name'])?></strong><small><?=$row['compliant_count']?> of <?=$row['required_count']?> required credentials current</small></span><b class="state-pill <?=$gap?'gap':'covered'?>"><?=$gap?$gap.' missing':'Compliant'?></b></div><?php endforeach;?><hr><form method="post" class="stack-form"><?=Csrf::field()?><input type="hidden" name="action" value="request_credential_renewal"><label>Credential<select name="member_credential_id"><?php foreach($credentials as $credential):?><option value="<?=$credential['id']?>"><?=esc($credential['staff_name'].' · '.$credential['credential_name'])?></option><?php endforeach;?></select></label><label>Due date<input type="date" name="due_on"></label><label>Note<input name="notes"></label><button class="button secondary">Request renewal</button></form></article>
<article class="panel"><h2>Labor safeguards</h2><form method="post" class="stack-form"><?=Csrf::field()?><input type="hidden" name="action" value="save_break_rule"><label>Shift threshold, minutes<input type="number" name="shift_minutes_threshold" min="60" value="<?=esc($laborOperations['rule']['shift_minutes_threshold'])?>"></label><label>Required break, minutes<input type="number" name="required_break_minutes" min="0" value="<?=esc($laborOperations['rule']['required_break_minutes'])?>"></label><button class="button primary">Save break rule</button></form><hr><form method="post" class="stack-form"><?=Csrf::field()?><input type="hidden" name="action" value="lock_labor_period"><label>Period start<input type="date" name="starts_on" required></label><label>Period end<input type="date" name="ends_on" required></label><button class="button secondary">Lock period</button></form><?php foreach($laborOperations['periods'] as $period):?><div class="planning-row"><span><strong><?=esc($period['starts_on'].' to '.$period['ends_on'])?></strong><small><?=esc(ucfirst($period['status']))?></small></span></div><?php endforeach;?></article>
<article class="panel"><h2>Time exceptions</h2><?php foreach($laborOperations['exceptions'] as $exception):?><form method="post" class="planning-row"><?=Csrf::field()?><input type="hidden" name="action" value="resolve_time_exception"><input type="hidden" name="exception_id" value="<?=$exception['id']?>"><span><strong><?=esc($exception['staff_name'].' · '.str_replace('_',' ',$exception['exception_type']))?></strong><small><?=esc($exception['exception_date'].' · '.$exception['status'])?></small></span><?php if($exception['status']==='open'):?><input name="notes" placeholder="Resolution"><button class="button primary" name="decision" value="resolved">Resolve</button><button class="button secondary" name="decision" value="dismissed">Dismiss</button><?php endif;?></form><?php endforeach;?><?php if(!$laborOperations['exceptions']):?><div class="inline-empty"><strong>No labor exceptions</strong></div><?php endif;?></article>
<article class="panel"><h2>Recommendation weights</h2><p class="auto-routing-note">Recommendations remain advisory. Managers make and document the final decision.</p><form method="post" class="stack-form"><?=Csrf::field()?><input type="hidden" name="action" value="save_fairness_settings"><?php foreach(['hours_weight'=>'Scheduled hours','opening_weight'=>'Openings','closing_weight'=>'Closings','weekend_weight'=>'Weekends','declined_offer_weight'=>'Declined offers','cost_weight'=>'Estimated cost'] as $key=>$label):?><label><?=$label?><input type="number" name="<?=$key?>" min="0" max="20" step=".25" value="<?=esc($fairnessOperations['settings'][$key])?>"></label><?php endforeach;?><button class="button primary">Save advisory weights</button></form></article>
<article class="panel"><h2>Recommendation outcomes</h2><form method="post" class="stack-form"><?=Csrf::field()?><input type="hidden" name="action" value="record_recommendation_outcome"><label>Shift<select name="shift_id"><?php foreach($shifts as $shift):?><option value="<?=$shift['id']?>"><?=esc($shift['shift_date'].' · '.$shift['department_name'])?></option><?php endforeach;?></select></label><label>Recommended employee<select name="recommended_membership_id"><option value="">None</option><?php foreach($data['people'] as $person):?><option value="<?=$person['membership_id']?>"><?=esc($person['name'])?></option><?php endforeach;?></select></label><label>Selected employee<select name="selected_membership_id"><option value="">None</option><?php foreach($data['people'] as $person):?><option value="<?=$person['membership_id']?>"><?=esc($person['name'])?></option><?php endforeach;?></select></label><label>Outcome<select name="outcome"><option value="accepted">Accepted</option><option value="declined">Declined</option><option value="overridden">Manager chose differently</option><option value="not_used">Not used</option></select></label><label>Manager reason<input name="manager_reason"></label><button class="button secondary">Record outcome</button></form><?php foreach($fairnessOperations['outcomes'] as $outcome):?><div class="planning-row"><span><strong><?=esc(ucfirst($outcome['outcome']))?></strong><small><?=$outcome['outcome_count']?> recorded outcomes</small></span></div><?php endforeach;?></article></section></main></body></html>
